import{_ as e,o as a,c as t,a4 as i}from"./chunks/framework.DCsBdTIw.js";const k=JSON.parse('{"title":"Hermes Agent","description":"将 Nous Research 的 Hermes Agent 接入 Tokeness，包含自定义网关必须显式声明的提示缓存设置。","frontmatter":{"title":"Hermes Agent","description":"将 Nous Research 的 Hermes Agent 接入 Tokeness，包含自定义网关必须显式声明的提示缓存设置。"},"headers":[],"relativePath":"zh/integrations/hermes.md","filePath":"zh/integrations/hermes.md","lastUpdated":1784332800000}'),d={name:"zh/integrations/hermes.md"};function n(o,s,h,l,p,r){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="hermes-agent" tabindex="-1">Hermes Agent <a class="header-anchor" href="#hermes-agent" aria-label="Permalink to &quot;Hermes Agent&quot;">​</a></h1><p>Hermes Agent 是 Nous Research 的开源智能体，支持两种传输协议：OpenAI 兼容的 Chat Completions，以及原生 Anthropic Messages。Tokeness 两者都支持。</p><h2 id="接入信息" tabindex="-1">接入信息 <a class="header-anchor" href="#接入信息" aria-label="Permalink to &quot;接入信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>传输协议</td><td><code>anthropic_messages</code>（调用 Claude 推荐）或 <code>openai_chat</code></td></tr><tr><td>Base URL（<code>anthropic_messages</code>）</td><td><code>https://n.tokeness.dev</code></td></tr><tr><td>Base URL（<code>openai_chat</code>）</td><td><code>https://n.tokeness.dev/v1</code></td></tr><tr><td>API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Model</td><td>从 Tokeness 控制台复制的完整模型名</td></tr></tbody></table><h2 id="_1-准备-tokeness" tabindex="-1">1. 准备 Tokeness <a class="header-anchor" href="#_1-准备-tokeness" aria-label="Permalink to &quot;1. 准备 Tokeness&quot;">​</a></h2><p>在 Tokeness 控制台完成：</p><ol><li>确认钱包余额可用。</li><li>创建 Hermes 专用 API Key。</li><li>复制要用的完整模型名（例如 <code>claude-opus-5-5</code>）。</li><li>打开使用日志，后面验证请求。</li></ol><h2 id="_2-配置-hermes" tabindex="-1">2. 配置 Hermes <a class="header-anchor" href="#_2-配置-hermes" aria-label="Permalink to &quot;2. 配置 Hermes&quot;">​</a></h2><p>编辑 <code>~/.hermes/config.yaml</code>。<strong>推荐把 Tokeness 配成一个自定义供应商（<code>provider: custom</code>）</strong>，密钥由该条目自己携带，避免 Hermes 的 Anthropic 凭据优先级（<code>ANTHROPIC_TOKEN</code> / Claude Code 凭据）把你的 Tokeness Key 顶掉或发错端点：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">claude-opus-5-5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://n.tokeness.dev</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  api_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic_messages</span></span></code></pre></div><p><code>api_mode</code> 决定传输协议，两种都受支持：</p><table tabindex="0"><thead><tr><th><code>api_mode</code></th><th>协议</th><th>对应端点</th></tr></thead><tbody><tr><td><code>anthropic_messages</code></td><td>原生 Anthropic Messages</td><td><code>https://n.tokeness.dev/v1/messages</code></td></tr><tr><td><code>chat_completions</code></td><td>OpenAI 兼容</td><td><code>https://n.tokeness.dev/v1/chat/completions</code></td></tr></tbody></table><p>用 OpenAI 兼容传输时，<code>base_url</code> 要带 <code>/v1</code>：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">claude-opus-5-5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://n.tokeness.dev/v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  api_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">chat_completions</span></span></code></pre></div><p><code>base_url</code> 不要重复拼 <code>/v1</code>（写成 <code>https://n.tokeness.dev/v1/v1</code> 会 404）。API Key 放 <code>~/.hermes/.env</code>，不要写进 <code>config.yaml</code>。</p><h2 id="_3-显式开启提示缓存" tabindex="-1">3. 显式开启提示缓存 <a class="header-anchor" href="#_3-显式开启提示缓存" aria-label="Permalink to &quot;3. 显式开启提示缓存&quot;">​</a></h2><p>Anthropic 的提示缓存是<strong>显式</strong>的：请求里必须带 <code>cache_control</code> 断点，上游才会缓存这段前缀；没有断点就每一轮按全价重算整段上下文。Hermes 自己会注入这些断点，但它只对<strong>能识别的供应商、域名和模型族</strong>注入；Tokeness 属于自定义端点，Hermes 的默认判定是保守的，也就是<strong>不注入</strong>。</p><p>这解释了为什么只改传输协议（<code>api_mode</code> 改成 Anthropic）不会让命中率变好——改协议不改变这个判定，只有显式声明才会。</p><p>在供应商条目下按模型声明。<strong><code>api</code> 必须与 <code>model.base_url</code> 逐字一致</strong>（Hermes 按归一化后的地址匹配路由，<code>/v1</code> 的有无是两条不同路由）：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">prompt_caching</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cache_ttl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;5m&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 或 &quot;1h&quot;；省略则用默认 5m</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tokeness</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://n.tokeness.dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 与 model.base_url 保持一致</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    transport</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">anthropic_messages</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 或 openai_chat</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    api_key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${TOKENESS_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    discover_models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 见第 4 步</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      claude-opus-5-5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        prompt_caching</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>要点：</p><ul><li><code>api</code> 必须与 <code>model.base_url</code> 写同一个值（含 <code>/v1</code> 与否），否则声明匹配不上、缓存仍然不生效。</li><li><code>models:</code> 下的键名必须与控制台里的完整模型名一致。</li><li><code>transport</code> 决定断点布局：<code>openai_chat</code> 用 OpenAI 信封布局，<code>anthropic_messages</code> 用原生块内布局。两种布局 Tokeness 都能正确转换，不必为了缓存而换协议。</li><li>省略 <code>prompt_caching</code> 时 Hermes 保持保守（不注入）；显式写 <code>false</code> 则强制关闭。</li><li>若使用 <code>api_mode: anthropic_messages</code>，Hermes <code>v2026.8.27</code> 及以后对 Claude 模型也会自动注入断点；但显式声明更稳妥，且在 OpenAI 兼容传输下是<strong>唯一</strong>的开启方式。</li></ul><h2 id="_4-模型名需要手动填写" tabindex="-1">4. 模型名需要手动填写 <a class="header-anchor" href="#_4-模型名需要手动填写" aria-label="Permalink to &quot;4. 模型名需要手动填写&quot;">​</a></h2><p>Tokeness 的 <code>/v1/models</code> 只返回公开分组（<code>default</code>）的模型。Claude、GPT 等付费分组不在这份公开清单里，因此 Hermes 对这些分组的模型自动发现会得到空列表。把 <code>discover_models</code> 设为 <code>false</code>，再按控制台里的完整模型名填写即可正常调用。</p><h2 id="_5-验证缓存是否生效" tabindex="-1">5. 验证缓存是否生效 <a class="header-anchor" href="#_5-验证缓存是否生效" aria-label="Permalink to &quot;5. 验证缓存是否生效&quot;">​</a></h2><ol><li>Hermes 启动时会打印缓存状态，例如 <code>💾 Prompt caching: ENABLED</code>。</li><li>在 Tokeness 控制台的<strong>使用日志</strong>里打开这次请求的详情，查看 <code>缓存写入</code> 与 <code>缓存读取</code>。</li><li>多轮对话的判断标准：</li></ol><table tabindex="0"><thead><tr><th>轮次</th><th>预期</th></tr></thead><tbody><tr><td>第一轮</td><td><code>缓存写入</code> 大于 0；输入 token 很小（写入部分按写入价计费）</td></tr><tr><td>后续轮</td><td><code>缓存读取</code> 大于 0；输入 token 同样很小</td></tr></tbody></table><p>如果每一轮的输入 token 都接近整段上下文、且 <code>缓存读取</code> 恒为 0，说明断点没有发出来，回到第 3 步检查声明。</p><h2 id="_6-排查" tabindex="-1">6. 排查 <a class="header-anchor" href="#_6-排查" aria-label="Permalink to &quot;6. 排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>401</td><td>检查 API Key；<code>anthropic_messages</code> 传输用 <code>x-api-key</code>，OpenAI 兼容传输用 <code>Authorization: Bearer</code></td></tr><tr><td>404</td><td><code>anthropic_messages</code> 的 <code>base_url</code> 填 <code>https://n.tokeness.dev</code>（不要再加 <code>/v1</code>）；OpenAI 兼容填 <code>https://n.tokeness.dev/v1</code></td></tr><tr><td>model not found</td><td>从控制台复制完整模型名；把 <code>discover_models</code> 设为 <code>false</code> 后手动填写</td></tr><tr><td>每轮输入 token 都很大、<code>缓存读取</code> 恒为 0</td><td>确认已声明 <code>prompt_caching: true</code>；确认 <code>providers.&lt;名&gt;.api</code> 与 <code>model.base_url</code> 完全一致；确认 <code>models:</code> 下的模型名与控制台一致</td></tr><tr><td>改了缓存配置但没有变化</td><td>该声明自 Hermes <code>v2026.8.27</code> 起生效，先确认版本</td></tr><tr><td>中途切换模型后费用突增</td><td>缓存按模型区分，换模型后第一轮必然全价重算整段上下文</td></tr></tbody></table>`,30)])])}const g=e(d,[["render",n]]);export{k as __pageData,g as default};
